/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Method,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import { CLEAR_SEARCH_BUTTON_LABEL, SEARCH_BUTTON_LABEL } from '../../a11y';
import { FormDataEvent, FormSize, IconPosition, Severity } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';
import { getDefaultSlotContent } from './search-field.utils';

/**
 * @nativeEvent click - dispatched when search field was clicked => 'event.target.value' delivers the value of input
 * @nativeEvent change - dispatched when search field input has changed => 'event.target.value' delivers the value of input
 * @nativeEvent input - dispatched on input => 'event.target.value' delivers the value of input
 *
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 * @slot noResultsContent - named slot 'noResultsContent', will be shown when no suggestions are available - here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-search-field',
  styleUrl: 'search-field.scss',
  shadow: { delegatesFocus: true },
})
export class SearchField implements ComponentInterface {
  /**
   * placeholder of the search-field
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * sets the size of the input field
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  /**
   * value of the search-field
   */
  @Prop({ reflect: true, mutable: true }) value: string = null;

  /**
   * highlights the matching substring
   */
  @Prop({ reflect: true }) readonly subStringHighlighting: boolean;

  /**
   * makes the highlighting case-insensitive, only useable with sub string highlighting
   */
  @Prop({ reflect: true }) readonly caseInsensitiveHighlighting: boolean;

  /**
   * sets the maximum amount of characters of the search-field
   */
  @Prop({ reflect: true }) readonly maxlength: number;

  /**
   * set max-height for the options container (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly maxHeight: string = 'none';

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * position of the magnifier icon
   */
  @Prop({ reflect: true }) readonly searchIconPosition: IconPosition = 'left';

  /**
   * opens the search field on focus even if no value is entered
   */
  @Prop({ reflect: true }) readonly directlyOpen: boolean;

  /**
   * hide search icon
   */
  @Prop({ reflect: true }) readonly hideSearchIcon: boolean = false;

  /**
   * hide clear icon
   */
  @Prop({ reflect: true }) readonly hideClearIcon: boolean = false;

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * specifies that an input must be filled out before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * severity of the searchfield
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity = 'none';

  /**
   * sets search-field to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * deactivate internal validations
   */
  @Prop({ reflect: true }) readonly noValidation: boolean;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * show status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons. Icon will become also the default icon for the suggestions
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * sets a custom accessible text for the clear button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-clear-button' }) readonly a11yLabelClearButton: string;

  /**
   * sets a custom accessible text for the search button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-search-button' }) readonly a11yLabelSearchButton: string;

  /**
   * if set, the search field will keep the popover open when a suggestion is selected
   */
  @Prop({ reflect: true }) readonly keepOpen: boolean = false;

  /**
   * is dispatched on keyboard enter or when search-icon is clicked
   */
  @Event() groupuiSearchStarted: EventEmitter<{ value: string }>;

  /**
   * is dispatched if a suggestion is selected. Emits the value of the suggestion if set, otherwise its text content in 'event.detail.value'
   */
  @Event() groupuiSuggestionSelected: EventEmitter<{ value: string; content: string }>;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<{ value: string }>;

  /**
   * for react user only - is dispatched when the value is changed on key input
   */
  @Event({ bubbles: false }) groupuiInput: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<void>;

  /**
   * is dispatched if the clear icon is clicked
   */
  @Event({ bubbles: false }) groupuiClearClicked: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * is dispatched when the input field of this search input is focused
   */
  @Event({ bubbles: false }) groupuiInputFocused: EventEmitter<void>;

  @State() isPopoverOpen: boolean = false;
  @State() suggestionsAvailable: boolean = false;
  @State() invalid: boolean;
  @State() focusOnClear: boolean;

  private backupValue: string = null;

  private INITIAL_INDEX: number = -1;

  private ariaAttributes: AriaAttributes;

  private searchSuggestionClickEventListeners: {
    suggestion: HTMLGroupuiSearchSuggestionElement;
    callback: () => void;
  }[] = [];

  @State() activeIndex: number = this.INITIAL_INDEX;

  @State() hasFocus: boolean;

  @Element() host: HTMLElement;

  @Watch('isPopoverOpen')
  onIsPopoverOpenChanged() {
    if (this.isPopoverOpen) {
      document.addEventListener('click', this.onClickListener);
    } else {
      document.removeEventListener('click', this.onClickListener);
    }
  }

  @Watch('invalid')
  onInvalidChange() {
    this.validity = this.getValidity();
    if (this.invalid) {
      this.severity = 'danger';
      this.host.dispatchEvent(new window.Event('invalid'));
      this.groupuiInvalid.emit();
    } else {
      this.severity = null;
    }
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (!this.suggestionsAvailable) return;

    switch (event.code) {
      case 'Escape':
        if (this.isPopoverOpen) {
          this.activeIndex = this.INITIAL_INDEX;
          this.focusInput();
          this.isPopoverOpen = false;
        }
        return;
      case 'ArrowDown':
        event.preventDefault();
        if (!this.isPopoverOpen) {
          this.isPopoverOpen = true;
          this.activeIndex = this.INITIAL_INDEX;
          return;
        }
        if (this.lastSuggestionFocused()) {
          this.changeActiveIndex(this.INITIAL_INDEX);
          return;
        }
        this.changeActiveIndex(this.activeIndex + 1);
        return;
      case 'ArrowUp':
        event.preventDefault();
        if (!this.isPopoverOpen) {
          this.isPopoverOpen = true;
          this.activeIndex = this.INITIAL_INDEX;
          return;
        }
        if (this.firstSuggestionFocused()) {
          this.changeActiveIndex(this.INITIAL_INDEX);
          return;
        }
        if (this.noSearchSuggestionSelected()) {
          this.changeActiveIndex(this.searchSuggestions().length - 1);
          return;
        }
        this.changeActiveIndex(this.activeIndex - 1);
        return;
      case 'Tab':
        this.isPopoverOpen = false;
        return;
      case 'Enter':
        if (this.focusOnClear) {
          this.clearInput(event);
        } else {
          event.preventDefault();
          this.optionSelected();
        }
        break;
      case 'Space':
        if (this.focusOnClear) {
          this.clearInput(event);
        }
        break;
    }
  }

  private changeActiveIndex(newIndex: number) {
    const oldIndex = this.activeIndex;
    this.activeIndex = newIndex;

    if (oldIndex === this.INITIAL_INDEX) {
      this.backupValue = this.value;
    }

    if (this.noSearchSuggestionSelected()) {
      this.focusInput();

      if (oldIndex > -1 && this.searchSuggestions().length === 0) {
        this.value = '';
      } else {
        this.value = this.backupValue;
      }
      return;
    }

    const focusedSuggestion = this.focusSelectedSuggestion();
    if (focusedSuggestion) {
      const suggestionTextContent = getDefaultSlotContent(focusedSuggestion);
      const suggestionValue = focusedSuggestion.value ? focusedSuggestion.value : focusedSuggestion.textContent;
      this.value = suggestionTextContent;
      this.setTextToHighlight(this.host.querySelectorAll('groupui-search-suggestion'), this.value);
      this.groupuiSuggestionSelected.emit({ value: suggestionValue, content: suggestionTextContent });
    }
  }

  @Listen('focusout')
  onBlur() {
    this.validateSearchfield();
    this.hasFocus = false;
  }

  @Listen('focusin')
  handleFocusin() {
    if (this.value || this.directlyOpen) {
      this.isPopoverOpen = true;
    }
    this.hasFocus = true;
  }

  @Watch('value')
  onValueChange() {
    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit({ value: this.value });
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.initSearchSuggestionIcons();
    this.activateCaseInsensitiveHighlighting();
  }

  componentDidLoad() {
    this.addFormsHandling();
    this.autofocus && this.focusInput();
    this.validity = this.getValidity();
    this.groupuiDidLoad.emit();
  }

  private getValidity() {
    return {
      valid: this.anySuggestionSelected() || !this.required,
      valueMissing: !this.anySuggestionSelected() && this.required,
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooLong: false,
      tooShort: false,
      typeMismatch: false,
    };
  }

  private noSearchSuggestionSelected() {
    return this.activeIndex === this.INITIAL_INDEX;
  }

  private focusSelectedSuggestion(): HTMLGroupuiSearchSuggestionElement | undefined {
    const focusedSuggestion = this.searchSuggestions()[this.activeIndex];
    // When rendered conditionally via ngFor in Angular,
    // the suggestions are sometimes not rendered in time, thus this additional check:
    if (focusedSuggestion && focusedSuggestion.focus) {
      focusedSuggestion.focus();
    }
    return focusedSuggestion;
  }

  private focusInput() {
    this.host.shadowRoot.querySelector('input').focus();
  }

  private lastSuggestionFocused() {
    return this.activeIndex === this.searchSuggestions().length - 1;
  }

  private firstSuggestionFocused() {
    return this.activeIndex === 0;
  }

  private onClickListener = (event: MouseEvent) => {
    if (this.isOutsideSearchField(event)) {
      this.isPopoverOpen = false;
    }
  };

  private isOutsideSearchField(event: MouseEvent) {
    return !event.composedPath().includes(this.host);
  }

  private initSearchSuggestionIcons() {
    this.searchSuggestions().forEach((suggestion: HTMLGroupuiSearchSuggestionElement) => {
      const individualSuggestionIcon = suggestion.getAttribute('icon');
      if (individualSuggestionIcon) return;
      suggestion.setAttribute('icon', this.icon || `search-24`);
    });
  }

  private searchSuggestions(): NodeListOf<HTMLGroupuiSearchSuggestionElement> {
    return this.host.querySelectorAll('groupui-search-suggestion');
  }

  private handleInput = (event: InputEvent) => {
    const input: HTMLInputElement = event.target as HTMLInputElement;

    this.subStringHighlighting &&
      this.setTextToHighlight(this.host.querySelectorAll('groupui-search-suggestion'), input.value);

    if (this.maxlength) {
      this.value = input.value.substring(0, this.maxlength);
    } else {
      this.value = input.value;
    }

    this.isPopoverOpen = true;

    this.groupuiInput.emit();
    this.focusInput();
  };

  private setTextToHighlight(searchSuggestions: NodeListOf<HTMLGroupuiSearchSuggestionElement>, text: string) {
    searchSuggestions?.forEach((searchSuggestion) => {
      searchSuggestion.setAttribute('input', text);
    });
  }

  private activateCaseInsensitiveHighlighting() {
    this.caseInsensitiveHighlighting &&
      this.host.querySelectorAll('groupui-search-suggestion')?.forEach((searchSuggestion) => {
        searchSuggestion.setAttribute('case-insensitive-highlighting', '');
      });
  }

  private handleChange = () => {
    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit({ value: this.value });
  };

  private clearInput = (event) => {
    this.changeActiveIndex(this.INITIAL_INDEX);
    this.value = '';
    this.isPopoverOpen = false;
    this.groupuiClearClicked.emit();
    this.subStringHighlighting && this.setTextToHighlight(this.host.querySelectorAll('groupui-search-suggestion'), '');
    event.preventDefault();
  };

  private handleSearch = (event) => {
    if (this.disabled) return;
    event.preventDefault();
    this.isPopoverOpen = false;
    this.groupuiSearchStarted.emit({ value: this.value });
  };

  private handleInputFocus = () => {
    this.groupuiInputFocused.emit();
  };

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private isShowNoSuggestionsSlot(): boolean {
    const hasNoSuggestionSlot = !!this.host.querySelector('[slot="noResultsContent"]');
    const hasSuggestions = this.searchSuggestions().length > 0;

    return hasNoSuggestionSlot && !hasSuggestions;
  }

  private suggestionsChanged = () => {
    this.backupValue = this.value;
    this.activeIndex = this.INITIAL_INDEX;

    this.suggestionsAvailable = this.searchSuggestions().length > 0;

    this.searchSuggestionClickEventListeners.forEach((listener) => {
      listener.suggestion.removeEventListener('click', listener.callback);
    });

    this.searchSuggestionClickEventListeners = Array.from(this.searchSuggestions()).map((suggestion, index) => {
      const callback = () => {
        if (!this.isIndexAlreadyActive(index)) {
          this.changeActiveIndex(index);
        }
        this.onOptionChanged();
      };

      suggestion.addEventListener('click', callback);
      return { suggestion, callback };
    });
  };

  private addFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event: Event) => {
      this.validateSearchfield();
      if (this.invalid) {
        event.preventDefault();
      }
    });
  }

  private validateSearchfield({ force = false }: { force?: boolean } = {}) {
    if (!force && this.noValidation) return;
    this.invalid = !this.anySuggestionSelected() && this.required;
  }

  private anySuggestionSelected(): boolean {
    return this.value !== null && this.value !== undefined && this.value.length > 0;
  }

  private isIndexAlreadyActive(index: number) {
    return this.activeIndex === index;
  }

  private optionSelected() {
    this.onOptionChanged();
    this.groupuiSearchStarted.emit({ value: this.value });
  }

  private onOptionChanged() {
    this.backupValue = this.value;
    this.focusInput();
    if (!this.keepOpen) {
      this.isPopoverOpen = false;
    }
  }

  /**
   * Clears the input, not emitting the clearClicked event.
   */
  @Method()
  async clear() {
    this.value = '';
    this.isPopoverOpen = false;
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.validateSearchfield({ force: true });
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private iconSize() {
    return this.size === 's' ? 16 : 24;
  }

  private getMaxHeight() {
    if (this.maxHeight !== 'none') return this.maxHeight;

    return 'none';
  }

  private showDescription() {
    if (!this.descriptionOnlyOnFocus) {
      return true;
    } else {
      return this.hasFocus;
    }
  }

  private getSearchIcon() {
    return this.icon || `search-${this.iconSize()}`;
  }

  private isClearIconVisible() {
    return this.value && !this.hideClearIcon;
  }

  private isSearchIconVisible() {
    return !this.hideSearchIcon;
  }

  private setFocusOnClear = () => {
    this.focusOnClear = true;
  };

  private removeFocusOnClear = () => {
    this.focusOnClear = false;
  };

  private getAriaLabelSearchButton = () => {
    if (this.a11yLabelSearchButton) return this.a11yLabelSearchButton;
    return SEARCH_BUTTON_LABEL;
  };

  private getAriaLabelClearButton = () => {
    if (this.a11yLabelClearButton) return this.a11yLabelClearButton;
    return CLEAR_SEARCH_BUTTON_LABEL;
  };

  render() {
    return (
      <Host data-show-clear-icon={String(this.isClearIconVisible())}>
        {this.isLabelSlotProvided() && (
          <label id="label" class={{ inline: !this.value }} aria-hidden="true">
            <slot name="label" />
          </label>
        )}

        <groupui-popover
          visible={this.isPopoverOpen && (this.suggestionsAvailable || this.isShowNoSuggestionsSlot())}
          full-width={true}
        >
          <div slot="parent" id="parent">
            <form onSubmit={this.handleSearch} class={{ expanded: !!this.isPopoverOpen }}>
              <input
                tabIndex={this.isPopoverOpen ? -1 : 0}
                onInput={this.handleInput}
                onChange={this.handleChange}
                onFocus={this.handleInputFocus}
                placeholder={this.placeholder}
                value={this.value}
                maxLength={this.maxlength}
                role="combobox"
                aria-controls="content"
                aria-expanded={this.isPopoverOpen ? 'true' : 'false'}
                aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
                aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
                {...this.ariaAttributes}
                disabled={this.disabled}
                class={{
                  expanded: !!this.isPopoverOpen,
                  'icon-right': this.searchIconPosition === 'right' && this.isSearchIconVisible(),
                  'no-search-icon': this.hideSearchIcon,
                }}
                autoFocus={this.autofocus}
              />
            </form>
            {this.useStatusIcon() && (
              <groupui-icon
                name={this.getStatusIcon()}
                width={this.iconSize()}
                height={this.iconSize()}
                class="status-icon"
                aria-hidden="true"
              />
            )}
            {this.isSearchIconVisible() && (
              <groupui-embedded-button
                id="search"
                onClick={this.handleSearch}
                class={`${this.searchIconPosition}`}
                aria-label={this.getAriaLabelSearchButton()}
                aria-describedby={this.isLabelSlotProvided() && !this.a11yLabelSearchButton ? 'label' : undefined}
                disabled={this.disabled}
                aria-hidden={this.disabled ? 'true' : null}
                icon={this.getSearchIcon()}
                size={this.size === 'm' ? 'xs' : 'xxs'}
                iconSource={this.iconSource}
              ></groupui-embedded-button>
            )}
            {this.isClearIconVisible() && (
              <groupui-embedded-button
                id="clear"
                onMouseDown={this.clearInput}
                class={`${this.searchIconPosition}`}
                aria-label={this.getAriaLabelClearButton()}
                aria-describedby={this.isLabelSlotProvided() && !this.a11yLabelClearButton ? 'label' : null}
                icon={`close-${this.iconSize()}`}
                size={this.size === 'm' ? 'xs' : 'xxs'}
                aria-hidden={this.disabled ? 'true' : null}
                disabled={this.disabled}
                onFocus={this.setFocusOnClear}
                onBlur={this.removeFocusOnClear}
              ></groupui-embedded-button>
            )}
          </div>

          <div slot="content" style={{ maxHeight: this.getMaxHeight() }} id="content">
            <slot onSlotchange={this.suggestionsChanged} />
            {this.isShowNoSuggestionsSlot() && (
              <div id="no-suggestions">
                <slot name="noResultsContent" />
              </div>
            )}
          </div>
        </groupui-popover>

        {this.isDescriptionSlotProvided() && this.showDescription() && (
          <div id="description" aria-hidden="true">
            <slot name="description" />
          </div>
        )}
      </Host>
    );
  }
}
